<template>
  <div class="cdek-page">
    <header class="cdek-nav"><div class="cdek-wrap nav-inner"><RouterLink to="/integrations/delivery" class="cdek-logo">СДЭК</RouterLink><nav><a href="#account">Главная</a><a href="#sender">Параметры отправки</a><a href="#tariffs">Тарифы</a><a href="#statuses">Статусы</a></nav><Button variant="outline" size="sm" as-child><RouterLink to="/integrations/delivery">К интеграциям</RouterLink></Button></div></header>
    <section class="hero"><div class="cdek-wrap hero-inner"><div><p class="eyebrow">НАСТРОЙКА ПРОФИЛЯ</p><h1>Интеграция с API СДЭК</h1><p>Прежде чем приступить к настройкам, убедитесь, что у вас есть договор со СДЭК и данные для сервиса «Интеграция». Ключи можно создать в личном кабинете СДЭК.</p></div><div class="hero-mark">CDEK<br><span>delivery</span></div></div></section>
    <main class="cdek-wrap form-wrap"><p class="intro">Все поля сохранены отдельно для магазина AGAIN. Изменения вступают в силу после нажатия кнопки «Сохранить настройки».</p>
      <section id="account" class="section"><h2>Аккаунт интеграции</h2><div class="two-col"><label>Аккаунт<Input v-model="form.account" placeholder="Укажите аккаунт…" autocomplete="off" /></label><label>Пароль<Input v-model="form.secure_password" type="password" placeholder="Оставьте пустым, чтобы не менять" autocomplete="new-password" /></label></div><p class="hint">Это не доступы от личного кабинета. В личном кабинете СДЭК откройте «Интеграция», нажмите «Создать ключ» и используйте полученные идентификатор и пароль.</p><label class="check"><input v-model="form.enabled" type="checkbox"><span>Интеграция СДЭК включена</span></label></section>
      <section id="sender" class="section"><h2>Параметры отправки</h2><label class="wide">Город отправки<Input v-model="form.sender.city_name" placeholder="Начните вводить город…" /><small>Укажите город и код СДЭК, из которого отправляются заказы.</small></label><div class="two-col"><label>Код города СДЭК<Input v-model.number="form.sender.city_code" type="number" min="1" placeholder="Например, 137" /></label><label>Название магазина<Input v-model="form.sender.name" placeholder="AGAIN" /></label><label>Адрес магазина<Input v-model="form.sender.address" placeholder="Адрес отправки" /></label><label>Почтовый индекс<Input v-model="form.sender.postal_code" placeholder="Индекс" /></label></div><div class="two-col compact"><label>Выберите режимы тарифов<select v-model="form.tariff_mode"><option value="any">Все тарифы</option><option value="dver">Тарифы от двери</option><option value="sklad">Тарифы от склада</option></select></label><label>Увеличить время доставки на, дней<Input v-model.number="form.delivery_days_offset" type="number" min="0" step="1" /></label></div></section>
      <section id="tariffs" class="section"><h2>Тарифы и габариты отправления</h2><div class="tariff-heading"><div><label>Тарифы</label><p class="hint">Выберите варианты, которые будут доступны покупателю. Если ничего не выбрано — покажем все доступные тарифы СДЭК.</p></div><Button type="button" variant="outline" :disabled="loadingTariffs" @click="loadTariffs">{{ loadingTariffs ? 'Обновляем…' : 'Настроить отображение тарифов' }}</Button></div><select v-model="form.tariff_codes" class="tariffs" multiple size="9"><option v-for="tariff in tariffs" :key="tariff.code" :value="tariff.code">{{ tariff.name }}</option></select><p class="hint">Для выбора нескольких тарифов удерживайте Ctrl / ⌘. Для постамата заказ должен состоять из одного грузоместа.</p><div class="two-col"><label>НДС для стоимости доставки<select v-model="form.delivery_vat"><option value="-1">БЕЗ НДС</option><option value="0">НДС 0%</option><option value="5">НДС 5%</option><option value="7">НДС 7%</option><option value="10">НДС 10%</option><option value="16">НДС 16%</option><option value="20">НДС 20%</option><option value="22">НДС 22%</option></select></label><label>Вес по умолчанию, г<Input v-model.number="form.default_package.weight" type="number" min="1" /></label></div><p class="subhead">Габариты отправления</p><div class="three-col"><label>Длина, см<Input v-model.number="form.default_package.length" type="number" min="0.1" max="255" step="0.1" /></label><label>Ширина, см<Input v-model.number="form.default_package.width" type="number" min="0.1" max="255" step="0.1" /></label><label>Высота, см<Input v-model.number="form.default_package.height" type="number" min="0.1" max="255" step="0.1" /></label></div><div class="radios"><label><input v-model="form.default_weight_scope" type="radio" value="item"> Вес по умолчанию задан для товара</label><label><input v-model="form.default_weight_scope" type="radio" value="order"> Вес по умолчанию задан для заказа</label></div><p class="hint">При передаче заказов в ПВЗ СДЭК измеряет фактический вес и габариты; итоговая стоимость может измениться.</p></section>
      <section id="services" class="section"><h2>Дополнительные услуги</h2><label class="check disabled"><input checked disabled type="checkbox"><span>Страхование</span></label><p class="hint">Страхование подключено автоматически для всех заказов.</p><div class="declared"><div><label>Назначить объявленную стоимость в размере<Input v-model.number="form.declared.percent" type="number" min="0" /></label></div><span>% от стоимости</span><label><input v-model="form.declared.type" type="radio" value="percent_product"> По умолчанию для товара</label></div><div class="declared"><div><label>Назначить фиксированную объявленную стоимость<Input v-model.number="form.declared.value" type="number" min="0" /></label></div><span>₽</span><div class="radios"><label><input v-model="form.declared.type" type="radio" value="fix_product"> Для товара</label><label><input v-model="form.declared.type" type="radio" value="fix_order"> Для заказа</label></div></div><p class="hint">Сумма страховой выплаты рассчитывается исходя из объявленной стоимости.</p><div class="checks"><label class="check"><input v-model="form.services.fitting" type="checkbox"><span>ПРИМЕРКА НА ДОМУ</span></label><label class="check"><input v-model="form.services.partial_delivery" type="checkbox"><span>ЧАСТИЧНАЯ ДОСТАВКА</span></label><label class="check"><input v-model="form.services.no_inspection" type="checkbox"><span>ЗАПРЕТ ОСМОТРА ВЛОЖЕНИЯ</span></label></div><label class="check"><input v-model="form.cod_pickup_only" type="checkbox"><span>Ограничить места самовывоза, поддерживающие наложенный платёж</span></label><p class="hint">При включении опции отображаются только ПВЗ, где доступна оплата при получении.</p></section>
      <section id="statuses" class="section"><h2>Импортировать статусы заказов</h2><label class="check"><input v-model="form.use_import" type="checkbox"><span>Обновлять заказы в системе при изменении трекинга СДЭК</span></label><p class="hint">Напротив каждого статуса магазина выберите статус СДЭК. При значении «нет» статус магазина не изменяется автоматически.</p><div v-if="form.use_import" class="status-table"><div class="table-head"><span>Статусы магазина</span><span>Статусы службы доставки СДЭК</span></div><div v-for="status in shopStatuses" :key="status.code" class="status-row"><label>{{ status.label }}</label><select v-model="form.status_mapping[status.code]"><option value="0">нет</option><option v-for="option in cdekStatuses" :key="option.code" :value="String(option.code)">{{ option.label }}</option></select></div></div></section>
      <section id="price" class="section"><h2>Модификация стоимости доставки</h2><label class="wide">Бесплатная доставка при сумме заказа<Input v-model.number="form.price_rules.threshold" type="number" min="0" /><small>Если указан 0, опция отключена. Основные правила бесплатной доставки можно настроить в разделе «Бесплатная доставка».</small></label><div class="rule-row"><label>Увеличить стоимость доставки на</label><Input v-model.number="form.price_rules.add_cost" type="number" min="0" /><select v-model="form.price_rules.add_cost_type"><option value="1">процент(-ов)</option><option value="2">рублей</option></select></div><div class="rule-row"><label>Увеличить стоимость заказа (РКО) на</label><Input v-model.number="form.price_rules.add_rko" type="number" min="0" /><select v-model="form.price_rules.add_rko_type"><option value="1">процент(-ов)</option><option value="2">рублей</option></select></div><div class="two-col"><label>Доп. стоимость доставки, ₽<Input v-model.number="form.price_rules.add_drc" type="number" min="0" /></label><label>Порог суммы заказа<Input v-model.number="form.price_rules.add_drc_adv" type="number" min="0" /></label><label>Округлять полученные значения<select v-model="form.price_rules.rounded"><option value="0">нет</option><option value="1">в большую сторону</option><option value="2">в меньшую сторону</option></select></label><label>Степень округления<select v-model="form.price_rules.roundper"><option value="0">—</option><option value="1">1</option><option value="2">10</option><option value="3">20</option><option value="4">50</option><option value="5">100</option></select></label></div></section>
      <section id="advanced" class="section"><h2>Экспериментальные возможности</h2><p>Ограничение загрузки ПВЗ</p><div class="radios"><label><input v-model="form.experimental.limitation_locality_mode" type="radio" value="region"> по региону</label><label><input v-model="form.experimental.limitation_locality_mode" type="radio" value="city"> по городу</label></div><p class="hint">ПВЗ на карте будут подгружаться по всему региону или по конкретному городу — в зависимости от выбранного режима.</p></section>
      <div class="savebar"><Button :disabled="saving" @click="save">{{ saving ? 'Сохраняем…' : 'Сохранить настройки' }}</Button></div>
    </main>
  </div>
</template>

<script setup lang="ts">
import { onMounted, ref } from 'vue'
import axios from 'axios'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
const shopStatuses = [{ code: 'new', label: 'Новый' }, { code: 'processing', label: 'В обработке' }, { code: 'approved', label: 'Согласован' }, { code: 'shipped', label: 'Отгружен' }, { code: 'exported', label: 'Отгружен на экспорт' }, { code: 'delivered', label: 'Доставлен' }, { code: 'return_process', label: 'В процессе возврата' }, { code: 'cancelled', label: 'Отменен' }, { code: 'returned', label: 'Возврат' }]
const cdekStatuses = [[1, 'Создан'], [2, 'Удален'], [3, 'Принят на склад отправителя'], [4, 'Вручен'], [5, 'Не вручен'], [6, 'Выдан на отправку в г.-отправителе'], [7, 'Сдан перевозчику в г.-отправителе'], [8, 'Отправлен в г.-получатель'], [9, 'Встречен в г.-получателе'], [10, 'Принят на склад доставки'], [11, 'Выдан на доставку'], [12, 'Принят на склад до востребования'], [13, 'Принят на склад транзита'], [14, 'Прозвонен получатель, готов к выдаче'], [15, 'Не удалось прозвонить'], [18, 'Возвращен на склад доставки'], [22, 'Встречен в г.-транзите'], [23, 'В процессе таможенного оформления (зарубеж)'], [24, 'В процессе таможенного оформления (РФ)'], [25, 'Отгружен в РФ'], [26, 'Таможенное оформление завершено'], [27, 'Отправлен в г. отправитель'], [28, 'Встречен в г. отправителе'], [29, 'Заложен в постамат']].map(([code, label]) => ({ code, label }))
const defaultForm = () => ({ enabled: false, account: '', secure_password: '', sender: { city_code: null as number | null, city_name: '', name: '', address: '', postal_code: '', phone: '' }, tariff_mode: 'any', tariff_codes: [] as number[], delivery_days_offset: 0, delivery_vat: '-1', default_package: { length: 26, width: 21, height: 4, weight: 80 }, default_weight_scope: 'item', services: { fitting: false, partial_delivery: false, no_inspection: false }, cod_pickup_only: false, declared: { percent: 0, value: 0, type: 'fix_product' }, use_import: true, status_mapping: { new: '0', processing: '1', approved: '0', shipped: '3', exported: '0', delivered: '4', return_process: '0', cancelled: '2', returned: '18' } as Record<string, string>, price_rules: { threshold: 0, add_cost: 0, add_cost_type: '1', add_rko: 0, add_rko_type: '1', add_drc: 0, add_drc_adv: 0, rounded: '0', roundper: '0' }, experimental: { limitation_locality_mode: 'city' } })
const form = ref(defaultForm()); const saving = ref(false); const loadingTariffs = ref(false); const tariffs = ref<Array<{ code: number, name: string }>>([])
const mergeSettings = (settings: any) => { const base = defaultForm(); form.value = { ...base, ...settings, sender: { ...base.sender, ...(settings.sender ?? {}) }, default_package: { ...base.default_package, ...(settings.default_package ?? {}) }, services: { ...base.services, ...(settings.services ?? {}) }, declared: { ...base.declared, ...(settings.declared ?? {}) }, status_mapping: { ...base.status_mapping, ...(settings.status_mapping ?? {}) }, price_rules: { ...base.price_rules, ...(settings.price_rules ?? {}) }, experimental: { ...base.experimental, ...(settings.experimental ?? {}) } } }
const api = 'third-party-integrations/cdek'
const loadTariffs = async () => { loadingTariffs.value = true; try { const { data } = await axios.get(`${api}/tariffs`); tariffs.value = data.tariffs ?? [] } finally { loadingTariffs.value = false } }
onMounted(async () => { try { const { data } = await axios.get(`${api}/settings`); mergeSettings(data.settings ?? {}) } finally { await loadTariffs() } })
const save = async () => { saving.value = true; try { await axios.put(`${api}/settings`, { settings: form.value }) } finally { saving.value = false } }
</script>

