nt-weight:600;margin:28px 0 14px}.radios{display:flex;flex-direction:column;gap:10px;margin:6px 0 16px}.radios label,.check{display:flex!important;flex-direction:row!important;align-items:center;gap:9px;font-weight:400!important}.check input{width:16px;height:16px;accent-color:#1c9a45}.disabled{opacity:.75}.declared{display:grid;grid-template-columns:minmax(220px,1fr) 100px minmax(200px,1fr);align-items:center;gap:16px;padding:16px 0;border-top:1px solid #e5e9e6}.checks{display:grid;gap:13px;margin:20px 0}.status-table{border:1px solid #e0e5e2}.table-head,.status-row{display:grid;grid-template-columns:1fr 1fr;gap:20px;align-items:center;padding:13px 16px}.table-head{background:#f4f7f5;font-size:13px;font-weight:600}.status-row{border-top:1px solid #e7ece9}.status-row label{font-weight:400!important}.rule-row{display:grid;grid-template-columns:minmax(220px,1fr) 160px 180px;gap:12px;align-items:center;margin:18px 0}.savebar{position:sticky;bottom:16px;display:flex;justify-content:center;padding:16px;background:rgba(255,255,255,.94);border:1px solid #dfe6e1;border-radius:5px;margin-top:22px}.savebar button{min-width:220px;background:#1c9a45;color:#fff}@media(max-width:720px){.nav-inner nav,.hero-mark{display:none}.two-col,.three-col,.declared,.table-head,.status-row,.rule-row{grid-template-columns:1fr}.section{padding:22px 18px}.hero h1{font-size:26px}.tariff-heading{flex-direction:column}.cdek-wrap{padding-left:16px;padding-right:16px}}
